package foodchain

import "strings"

// animals is the cumulative sequence of creatures, in the order they appear
// in the song. Index 0 is the fly (the first swallowed), index 7 is the horse.
var animals = []string{"fly", "spider", "bird", "cat", "dog", "goat", "cow", "horse"}

// comments holds the reaction line that follows the first line of each verse.
// For the fly it doubles as the closing line, and for the horse it is the
// final line of the whole song.
var comments = []string{
	"I don't know why she swallowed the fly. Perhaps she'll die.",
	"It wriggled and jiggled and tickled inside her.",
	"How absurd to swallow a bird!",
	"Imagine that, to swallow a cat!",
	"What a hog, to swallow a dog!",
	"Just opened her throat and swallowed a goat!",
	"I don't know how she swallowed a cow!",
	"She's dead, of course!",
}

// ending is the line that closes every verse except the last.
const ending = "I don't know why she swallowed the fly. Perhaps she'll die."

// Verse returns the lyrics for a single verse, where v is 1-based.
func Verse(v int) string {
	var b strings.Builder
	b.WriteString("I know an old lady who swallowed a " + animals[v-1] + ".\n")
	b.WriteString(comments[v-1] + "\n")

	// The fly verse and the horse verse have no catch-chain.
	if v == 1 || v == len(animals) {
		return strings.TrimRight(b.String(), "\n")
	}

	// Build the cumulative chain: each swallowed creature was to catch the
	// one before it, working back down to the fly.
	for k := v - 1; k >= 1; k-- {
		line := "She swallowed the " + animals[k] + " to catch the " + animals[k-1]
		if animals[k-1] == "spider" {
			line += " that wriggled and jiggled and tickled inside her."
		}
		b.WriteString(line + ".\n")
	}
	b.WriteString(ending)
	return b.String()
}

// Verses returns the lyrics for verses start through end, inclusive.
func Verses(start, end int) string {
	verses := make([]string, 0, end-start+1)
	for v := start; v <= end; v++ {
		verses = append(verses, Verse(v))
	}
	return strings.Join(verses, "\n\n")
}

// Song returns the complete song.
func Song() string {
	return Verses(1, len(animals))
}

